package com.bank.flink.apis;

import java.math.BigDecimal;

// A transaction used by both the declarative and low-level examples.
class Txn {
    private final String txnId;
    private final String accountId;
    private final String branch;
    private final BigDecimal amount;

    Txn(String txnId, String accountId, String branch, BigDecimal amount) {
        this.txnId = txnId;
        this.accountId = accountId;
        this.branch = branch;
        this.amount = amount;
    }

    String getTxnId() { return txnId; }
    String getAccountId() { return accountId; }
    String getBranch() { return branch; }
    BigDecimal getAmount() { return amount; }
}
