package com.bank.flink.apis;

import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;

// Models the Table API / Flink SQL style: a concise relational GROUP BY SUM.
// In real Flink this is one SQL statement; here we show the equivalent result.
class DeclarativeAggregator {
    private static final Logger log = Logger.getLogger(DeclarativeAggregator.class.getName());

    Map<String, BigDecimal> sumByBranch(List<Txn> txns) {
        Map<String, BigDecimal> totals = new LinkedHashMap<>();
        for (Txn t : txns) {
            totals.merge(t.getBranch(), t.getAmount(), BigDecimal::add);
        }
        log.info(() -> "declarative GROUP BY branch SUM -> " + totals);
        return totals;
    }
}
