package com.bank.flink.apis;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;

// Models the DataStream ProcessFunction style: per-account state + a dynamic
// threshold that evolves with behavior. This custom logic is awkward in SQL.
class LowLevelFraudDetector {
    private static final Logger log = Logger.getLogger(LowLevelFraudDetector.class.getName());

    // Per-account keyed state: the running dynamic threshold.
    private final Map<String, BigDecimal> thresholdState = new HashMap<>();
    private static final BigDecimal INITIAL_THRESHOLD = new BigDecimal("40000");
    private static final BigDecimal GROWTH = new BigDecimal("1.2"); // threshold adapts up

    List<String> process(List<Txn> txns) {
        List<String> flags = new ArrayList<>();
        for (Txn t : txns) {
            BigDecimal threshold = thresholdState.getOrDefault(t.getAccountId(), INITIAL_THRESHOLD);
            if (t.getAmount().compareTo(threshold) > 0) {
                String flag = "FRAUD FLAG " + t.getTxnId() + " account=" + t.getAccountId()
                        + " amount=" + t.getAmount() + " > threshold=" + threshold;
                flags.add(flag);
                log.warning(() -> flag);
            } else {
                log.info(() -> "ok " + t.getTxnId() + " amount=" + t.getAmount()
                        + " <= threshold=" + threshold);
            }
            // Dynamic rule: threshold adapts upward after each txn for this account.
            thresholdState.put(t.getAccountId(),
                    threshold.multiply(GROWTH).setScale(0, java.math.RoundingMode.HALF_UP));
        }
        return flags;
    }
}
