package com.bank.flink.apis;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class ApiChoiceDemo {
    private static final Logger log = Logger.getLogger(ApiChoiceDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        List<Txn> txns = List.of(
            new Txn("T1", "SAV2001", "MUMBAI", new BigDecimal("50000")),
            new Txn("T2", "CUR3001", "DELHI",  new BigDecimal("12000")),
            new Txn("T3", "SAV2001", "MUMBAI", new BigDecimal("30000")),
            new Txn("T4", "CUR3001", "DELHI",  new BigDecimal("8000")),
            new Txn("T5", "SAV2001", "MUMBAI", new BigDecimal("90000"))
        );

        // Declarative (Table API / Flink SQL): trivial relational analytic.
        log.info("=== Declarative (use Table API / Flink SQL) ===");
        new DeclarativeAggregator().sumByBranch(txns);

        // Low-level (DataStream ProcessFunction): custom per-account dynamic rule.
        log.info("=== Low-level (use DataStream ProcessFunction) ===");
        List<String> flags = new LowLevelFraudDetector().process(txns);
        log.info("fraud flags = " + flags);
    }
}

